#define R(p,a,r)mix(a*dot(p,a),p,cos(r))+sin(r)*cross(p,a)
#define H(h)(cos((h)*6.3+vec3(0,23,21))*.5+.5)
#define MAX_STEPS 100
#define MAX_DIST 100.
#define SURF_DIST 0.001

const float PI = 3.14159265;

mat3 rotate( in vec3 v, in float angle)
{
 float c = cos(radians(angle));
 float s = sin(radians(angle));	
 return mat3(c + (1.0 - c) * v.x * v.x, (1.0 - c) * v.x * v.y - s * v.z, (1.0 - c) * v.x * v.z + s * v.y,
 (1.0 - c) * v.x * v.y + s * v.z, c + (1.0 - c) * v.y * v.y, (1.0 - c) * v.y * v.z - s * v.x,
 (1.0 - c) * v.x * v.z - s * v.y, (1.0 - c) * v.y * v.z + s * v.x, c + (1.0 - c) * v.z * v.z
 );
}


float sdOctahedron( vec3 p, float s)
{
  return (p.y+p.z)*0.735027;
}

mat2 Rot(float a) {
 float s = sin(a);
 float c = cos(a);
 return mat2(c, -s, s, c);
}

float smin( float a, float b, float k ) {
 float h = clamp( 0.5+0.5*(b-a)/k, 0., 1. );
 return mix( b, a, h ) - k*h*(1.0-h);
}


vec2 condmin(in vec2 d1, in vec2 d2) {
 return vec2(min(d1.x, d2.x), mix(d1.y, d2.y, step(d2.x, d1.x)));
}

float g1;

vec2 GetDist(vec3 p) {
 vec2 d;
 d.x =p.y +10.;
  p.yz *= Rot(0.2831*iTime);
 p.xz *= Rot(0.2831*iTime);
 for(int i=0; i<7; i++)
 {
  p = abs(p);

   p = rotate( normalize( vec3(1.3 ,-.1,2. ) ), sin(59.*0.2)*80.)*p;
  vec2 dbox = vec2(sdOctahedron( p- vec3(-0.,abs(sin(p.y)),abs(sin(p.z)*1.5)),1.),1.);
  if( dbox.x < d.x)
  {
   g1 +=3./(0.6+pow(abs(dbox.x),10.));
   d = condmin( d,dbox);
  }	
 }
 return d ;
}

vec2 RayMarch(vec3 ro, vec3 rd) {
vec2 h, t=vec2( 0.);  
for (int i=0; i<64; i++) 
 {   
  h = GetDist(ro + t.x * rd);   

  t.x+=h.x *.6;

 }
 if(t.x>70.) 
 t.x=.0;
return t;
}


vec3 GetNormal(vec3 p){
 vec2 d = GetDist(p);
 vec2 e = vec2(0.001,0);
 vec3 n = d.x - vec3(
 GetDist(p-e.xyy).x,
 GetDist(p-e.yxy).x,
 GetDist(p-e.yyx).x);
 return normalize(n);
}

float GetLight(vec3 p) {
 vec3 lightPos = vec3(sin(iTime),cos(iTime),0.);
 vec3 l = normalize(lightPos-p);
 vec3 n = GetNormal(p);
 float dif = clamp(dot(n, l)*.5+.5, 0., 1.);


 return dif;       
}

vec3 R3(vec2 uv, vec3 p, vec3 l, float z) {
 vec3 f = normalize(l-p),
 r = normalize(cross(vec3(0,1,0), f)),
 u = cross(f,r),
 c = p+f*z,
 i = c + uv.x*r + uv.y*u,
 d = normalize(i-p);
 return d;
}

void mainImage(out vec4 O, vec2 C)
{
    O=vec4(0);
    vec3 p,q,r=iResolution,
    d=normalize(vec3((C*2.-r.xy)/r.y,1));  
     vec2 uv = (C-.5*iResolution.xy)/iResolution.y;

 vec3 col = vec3(0);  
 vec3 ro = vec3(-3, -10., 1.);
 ro.yz *= Rot(6.2831+iTime);
 ro.xz *= Rot(6.2831+iTime);


 vec3 rd = R3(uv, ro, vec3(0,0,0), .7);
 vec2 d3 = RayMarch(ro, rd);   
 float t =d3.x *1.;   
 if(t>0.){
 vec3 p = ro + rd *t;
 vec3 baseColor = vec3(1.,1.,0.);

 float dif = GetLight (p); 
 col = vec3(dif);  

 float fog = 1. / (1. + t * t * .004);

 }
 vec3 sky = vec3(1., 1., 1.);

 col *=g1*vec3(.001);
    for(float i=0.,a,s,e,g=0.;
        ++i<70.;
        O.xyz+=mix(vec3(0.1,1.,3.),H(g*.1),.8)*8./e/8e3
    )
    {
        p=g*d*col;

        a=30.;
        p=mod(p-a,a*2.)-a;
        s=3.;
        for(int i=0;i++<8;){
            p=.3-abs(p);
            p.x<p.z?p=p.zyx:p;
            p.z<p.y?p=p.xzy:p;
            s*=e=1.4+sin(iTime*.1)*.1;
            p=abs(p)*e-
                vec3(
                    5.+sin(iTime*.03+.5*sin(iTime*.03))*3.,
                    120,
                    8.+cos(iTime*.05)*5.
                 );
         }
         g+=e=length(p.yzzz)/s;
    }
}
